#!/usr/bin/env bash
# Vergleicht zwei OrcaSlicer-G-Code-Dateien byteweise – nach Entfernen der
# einzigen tatsaechlich zeitlich variablen Zeile im Orca-2.4.2-Header:
#
#   ; generated by OrcaSlicer 2.4.2 on YYYY-MM-DD at HH:MM:SS
#
# Weitere typische Varianzquellen (Hostname, UUIDs, Random-Seeds) kommen in
# den von uns verglichenen OrcaSlicer-2.4.2-Headern NICHT vor; wurde geprueft,
# siehe docs/engine-integration.md.
#
# Verwendung: compare-gcode.sh ref.gcode ours.gcode
#   → gibt gefilterte Hashes aus und 0, wenn identisch

set -euo pipefail

if [ "$#" -ne 2 ]; then
    echo "Usage: $0 ref.gcode ours.gcode" >&2
    exit 2
fi

REF="$1"
OURS="$2"

# Der Filter: entfernt genau die eine Header-Zeitstempel-Zeile.
# -E "regex": generated by OrcaSlicer <version> on <date> at <time>
FILTER_REGEX='^; generated by OrcaSlicer .* on [0-9-]+ at [0-9:]+$'

sha_ref=$(grep -vE "$FILTER_REGEX" "$REF"  | sha256sum | awk '{print $1}')
sha_our=$(grep -vE "$FILTER_REGEX" "$OURS" | sha256sum | awk '{print $1}')

echo "ref  (gefiltert): $sha_ref  $(wc -l <"$REF") Zeilen (roh)"
echo "ours (gefiltert): $sha_our  $(wc -l <"$OURS") Zeilen (roh)"

if [ "$sha_ref" = "$sha_our" ]; then
    echo "IDENTISCH"
    exit 0
else
    echo "UNTERSCHIEDLICH"
    echo "--- Diff (gefiltert, erste 50 Zeilen Unterschied) ---"
    diff <(grep -vE "$FILTER_REGEX" "$REF") <(grep -vE "$FILTER_REGEX" "$OURS") | head -50
    exit 1
fi
